import {Form as Material} from "./1Adding Interactivity/4UpdatingObjects"
import Root from "./1Adding Interactivity/4UpdatingObjects"
import Sub from "./subReLearn"
import "./ReLearn.css"
import { useState } from "react"

export default function () {
  const [obj, setObj] = useState({})
  return (
    <>
    <input value={obj.inputF} onInput={(e) => {setObj({...obj, inputF: e.target.value})}}/> <br/>
    <input value={obj.inputL} onInput={(e) => {setObj({...obj, inputL: e.target.value})}}/>
    <p>{}</p>
    </>
  );
}



